            aOrbiterA = (((aWandererI + RotL64(aPrevious, 21U)) + RotL64(aCarry, 51U)) + 0xEFC96D199DDB1D51ULL) + aOASaltF[(((511U - aIndex) + 206U)) & S_SALT1];
