            aOrbiterG = ((aWandererH + RotL64(aCross, 14U)) + RotL64(aCarry, 39U)) + 0x9B47D8ACB6CE06FDULL;
            aOrbiterD = (aWandererK + RotL64(aScatter, 3U)) + 0xA52DC5B2A6D887CCULL;
