            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x06A6A25DDAC44F73ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterF) ^ 0xF9867BCCE59A4F8EULL) ^ aOUSaltE[(((511U - aIndex) + 407U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xBDE431C6B88901DBULL), 35U);
