            aScatter = (RotL64(aPrevious, 37U) + RotL64(aCarry, 19U)) ^ (RotL64(aCross, 5U) + RotL64(aIngress, 56U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
