            aWandererA = aWandererA ^ ((RotL64(aPrevious, 3U) + RotL64(aOrbiterI, 48U)) + aOrbiterD);
            aWandererG = aWandererG + (((RotL64(aIngress, 46U) + RotL64(aOrbiterE, 57U)) + aOrbiterI) + RotL64(aCarry, 51U));
            //
            aCarry = aCarry + (aWandererE ^ RotL64(aWandererJ, 3U));
