            aOrbiterI = RotL64((aOrbiterI * 0x1D293817E49DB793ULL), 21U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xB3CA37562D8D3D66ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0xF4BEFD51247A9ED4ULL) ^ aOUSaltD[((aIndex + 380U)) & S_SALT1];
