            aOrbiterC = (((aWandererE + RotL64(aCross, 13U)) + RotL64(aCarry, 53U)) + 0x808F3FAAE114E1A8ULL) + aOASaltB[((aIndex + 281U)) & S_SALT1];
            aOrbiterE = ((aWandererF + RotL64(aPrevious, 5U)) + RotL64(aCarry, 11U)) + 0x3835BE1A2907217BULL;
            aOrbiterK = (aWandererA + RotL64(aIngress, 41U)) + 0xB07A0EE5A6960E94ULL;
