            aOrbiterC = RotL64((aOrbiterC * 0x3B69CCE9952E6F41ULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0xC82B020C2AE9911EULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x1D5E9245935110DDULL;
            aOrbiterE = RotL64((aOrbiterE * 0x180EAA0FCC32C345ULL), 57U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0x99AD9F297B79EAFEULL) + aOUSaltG[((aIndex + 392U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0x1E2E2F82C8E8B245ULL) ^ aOUSaltC[(((511U - aIndex) + 450U)) & S_SALT1];
