            aIngress = aIngress + (RotL64(aOrbiterI, 14U) ^ aOrbiterC);
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterB, 23U));
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterD, 53U));
            aIngress = aIngress + RotL64(aOrbiterA, 47U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ (((RotL64(aIngress, 37U) + RotL64(aOrbiterA, 47U)) + aOrbiterD) + aWUSaltD[((aIndex + 118U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aCross, 53U) + aOrbiterB) + RotL64(aOrbiterI, 19U));
