            aWandererG = aWandererG ^ ((RotL64(aPrevious, 19U) + aOrbiterE) + RotL64(aOrbiterB, 53U));
            aWandererJ = aWandererJ + ((((RotL64(aScatter, 11U) + RotL64(aOrbiterA, 24U)) + aOrbiterI) + RotL64(aCarry, 21U)) + aWUSaltC[((aIndex + 316U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aPrevious, 5U) + RotL64(aOrbiterJ, 21U)) + aOrbiterB) + aWUSaltE[(((511U - aIndex) + 385U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aIngress, 22U) + aOrbiterF) + RotL64(aOrbiterI, 35U));
            aWandererC = aWandererC ^ ((RotL64(aCross, 47U) + aOrbiterB) + RotL64(aOrbiterH, 29U));
            //
            aCarry = aCarry + (aWandererG ^ RotL64(aWandererK, 14U));
