            aOrbiterK = ((aWandererH + RotL64(aScatter, 27U)) + RotL64(aCarry, 53U)) + 0x657B442D42A25EF5ULL;
            aOrbiterB = ((aWandererD + RotL64(aPrevious, 37U)) + 0x754B7CDC4E90F61AULL) + aOASaltC[(((511U - aIndex) + 444U)) & S_SALT1];
            aOrbiterA = ((aWandererA + RotL64(aScatter, 3U)) + 0x72AA6371E8B98270ULL) + aOASaltB[((aIndex + 500U)) & S_SALT1];
