            aScatter = (RotL64(aCross, 54U) ^ RotL64(aPrevious, 27U)) + (RotL64(aCarry, 41U) + RotL64(aIngress, 11U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = ((aWandererF + RotL64(aIngress, 57U)) + 0xE17C2385422AB7A0ULL) + aOASaltA[(((511U - aIndex) + 445U)) & S_SALT1];
            aOrbiterJ = ((aWandererC + RotL64(aScatter, 29U)) + RotL64(aCarry, 29U)) + 0x89882226C8226288ULL;
            aOrbiterC = ((aWandererB + RotL64(aPrevious, 6U)) + 0x8FA824ECB496A378ULL) + aOASaltG[((aIndex + 271U)) & S_SALT1];
            aOrbiterE = (aWandererA + RotL64(aCross, 43U)) + 0x965A217942930D19ULL;
            aOrbiterH = (((aWandererD + RotL64(aIngress, 21U)) + RotL64(aCarry, 3U)) + 0xE96592A22064F776ULL) + aOASaltB[((aIndex + 440U)) & S_SALT1];
            aOrbiterB = ((aWandererK + RotL64(aPrevious, 37U)) + 0xF6AB0C3E63549223ULL) + aOASaltE[(((511U - aIndex) + 343U)) & S_SALT1];
            aOrbiterI = (((aWandererH + RotL64(aCross, 51U)) + RotL64(aCarry, 47U)) + 0x43F5C9E1122A90FAULL) + aOASaltC[((aIndex + 253U)) & S_SALT1];
