            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0x685E415E9C081AC7ULL) + aOUSaltE[((aIndex + 64U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xB9D14854A8553553ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x2364563343F4D2BBULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0x4D216FA79CFCAC30ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0xF5AD2BBB5C58D1A7ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xA6522427B51E18D9ULL), 13U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0xAA271252F42BB153ULL) + aOUSaltA[(((511U - aIndex) + 391U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x761F798D0FB4E3B8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x9DD2372B0132898BULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x055D7E9A54101F4EULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterI) ^ 0xC5480BEB4F61AF67ULL) ^ aOUSaltB[(((511U - aIndex) + 312U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xDF93623175C62735ULL), 51U);
