            aScatter = (RotL64(aPrevious, 35U) ^ RotL64(aCross, 11U)) + (RotL64(aIngress, 23U) ^ RotL64(aCarry, 50U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
