            aOrbiterH = ((aWandererC + RotL64(aIngress, 53U)) + 0xC3AB17B92E65BC40ULL) + aOASaltF[((aIndex + 369U)) & S_SALT1];
            aOrbiterI = (((aWandererK + RotL64(aCross, 27U)) + RotL64(aCarry, 41U)) + 0x7550D34673B9C80AULL) + aOASaltD[((aIndex + 509U)) & S_SALT1];
